import React, { useRef, useState } from "react";

// ====================================================================
// 1. MOCKING ASSETS & COMPONENTS (For self-containment)
// Ces assets et composants sont définis ici pour rendre le fichier runnable
// car les imports de fichiers locaux (assets/img) et de composants externes
// (components/calendar, components/newsStack) ne sont pas disponibles.
// ====================================================================

// --- Mock Image Assets (using placeholder URLs) ---
const sankara = "https://placehold.co/150x150/000000/FFFFFF?text=Sankara";
const site1_baobab = "https://placehold.co/300x120/4682B4/FFFFFF?text=Heritage+Cloud";
const accel_png = "https://placehold.co/100x40/FFFFFF/1e204a?text=ACCEL";
const site2_accel = "https://placehold.co/300x120/1e204a/FFFFFF?text=Accel+Site";
const ressourcesImg = "https://placehold.co/1200x400/8B0000/FFFFFF?text=Ressources";
const shirikia_png = "https://placehold.co/300x120/3CB371/FFFFFF?text=Shirikia";
const BannerImage = "https://placehold.co/1200x500/A9A9A9/000000?text=Banner";
const ChatbotIcon = "https://placehold.co/60x60/25509d/FFFFFF?text=AI";
const HeroImage = "https://placehold.co/1920x860/A0522D/FFFFFF?text=Hero+BG";
const News1 = "https://placehold.co/300x180/DDA0DD/000000?text=News+1";
const News2 = "https://placehold.co/300x180/E6E6FA/000000?text=News+2";
const News3 = "https://placehold.co/300x180/ADD8E6/000000?text=News+3";
const birthday = "https://placehold.co/48x48/FFD700/000000?text=B'Day";
const seynabou = "https://placehold.co/150x150/FFC0CB/000000?text=Seyn%C3%A9dou";
const tamsir = "https://placehold.co/150x150/ADD8E6/000000?text=Tamsir";
const ndeye = "https://placehold.co/150x150/90EE90/000000?text=Ndeye";
const placeholderImage = "https://placehold.co/120x120/E0E0E0/333333?text=N/A";

// Nouveaux assets pour la section flottante
const FloatingImage1 = "https://placehold.co/64x64/2f5ac8/FFFFFF?text=Site+A";
const FloatingImage2 = "https://placehold.co/64x64/6B8E23/FFFFFF?text=Site+B";
const FloatingImage3 = "https://placehold.co/64x64/FF6347/FFFFFF?text=Site+C";
const FloatingImage4 = "https://placehold.co/64x64/00CED1/FFFFFF?text=Site+D";
const FloatingImage5 = "https://placehold.co/64x64/8A2BE2/FFFFFF?text=Site+E";


// --- Mock IndexNavbar Component ---
const IndexNavbar = ({ fixed }) => (
  <header className={`bg-[#20264e] text-white p-4 ${fixed ? 'fixed top-0 w-full z-50' : ''}`}>
    <div className="max-w-7xl mx-auto flex justify-between items-center">
      <h1 className="text-xl font-bold">Portal Dashboard</h1>
      {/* Simulation des liens de navigation */}
      <nav className="hidden md:flex space-x-6 text-sm">
        <a href="#accueil" className="hover:text-fuchsia-400 transition-colors">Accueil</a>
        <a href="#actualites" className="hover:text-fuchsia-400 transition-colors">Actualités</a>
        <a href="#contact" className="hover:text-fuchsia-400 transition-colors">Contact</a>
      </nav>
    </div>
  </header>
);

// --- Mock PrettyCalendar Component ---
const PrettyCalendar = () => (
  <div className="bg-white p-4 rounded-xl shadow-lg border border-blueGray-100 max-w-sm md:max-w-none">
    <div className="text-center font-bold text-lg mb-2 text-[#25509d]">Octobre 2025</div>
    <div className="grid grid-cols-7 gap-1 text-xs">
      {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map((day) => (
        <div key={day} className="text-center font-semibold text-gray-500">{day}</div>
      ))}
      {[...Array(31)].map((_, i) => (
        <div key={i} className={`p-2 rounded-full text-center hover:bg-gray-100 transition-colors cursor-pointer ${i + 1 === 9 ? 'bg-[#25509d] text-white font-bold' : 'text-gray-800'}`}>
          {i + 1}
        </div>
      ))}
    </div>
  </div>
);

// --- Mock NewsStack Component ---
const NewsStack = ({ items }) => (
  <div className="flex flex-col gap-4">
    {items.map((item, i) => (
      <a
        key={i}
        href={item.href}
        className="block bg-white rounded-xl shadow-lg overflow-hidden transition duration-300 hover:shadow-xl hover:translate-y-[-2px] active:translate-y-[0px]"
      >
        <img
          src={item.img}
          alt={`Actualité ${i + 1}`}
          className="w-full h-32 object-cover object-center"
        />
        <div className="p-3 text-sm text-gray-700 font-medium">
          Titre de l'actualité {i + 1}
        </div>
      </a>
    ))}
  </div>
);

// --- Footer Component (Fix: Blue Background) ---
const Footer = () => {
  // Simuler Accel Logo
  const AccelLogoLight = 'https://placehold.co/100x40/FFFFFF/1e204a?text=ACCEL';
  const accel_png = AccelLogoLight;

  return (
    <footer
      id="contact"
      className="bg-[#1e204a] text-white py-12 px-4"
    >
      <div className="max-w-7xl mx-auto grid grid-cols-2 md:grid-cols-4 gap-8 md:gap-10 text-sm">
        <div className="col-span-2 md:col-span-1">
          <p className="text-lg font-bold mb-2">Powered By</p>
          <img src={accel_png} alt="Accel Logo" className="h-16 sm:h-20" />
        </div>
        <div>
          <h3 className="font-bold mb-4 uppercase tracking-wide">Liens utiles</h3>
          <ul className="space-y-3">
            <li>🔗 Red Hat Enterprise Linux</li>
            <li>🔗 Openshift AI</li>
            <li>🔗 Heritage Cloud</li>
          </ul>
        </div>
        <div>
          <h3 className="font-bold mb-4 uppercase tracking-wide">Contact</h3>
          <ul className="space-y-3">
            <li>+221 33 820 83 83</li>
            <li>info@accel-tech.net</li>
            <li>165 virage, Route de l'aéroport, Dakar, Sénégal</li>
          </ul>
        </div>
        <div className="flex items-start md:items-center justify-start md:justify-center gap-6 text-fuchsia-400 text-2xl">
          {/* Icones Font Awesome (simulées par texte) */}
          <span className="hover:text-white transition-colors cursor-pointer" aria-label="Facebook">📘</span>
          <span className="hover:text-white transition-colors cursor-pointer" aria-label="LinkedIn">💼</span>
          <span className="hover:text-white transition-colors cursor-pointer" aria-label="YouTube">▶️</span>
        </div>
      </div>
    </footer>
  );
};


// ====================================================================
// 2. COMPOSANT PRINCIPAL INDEX
// ====================================================================

export default function Index() {
  const twoColRef = useRef(null);
  const [chatOpen, setChatOpen] = useState(false);

  return (
    <>
      <IndexNavbar fixed />

      {/* HERO (Alex superposé ici) */}
      <section
        id="accueil"
        className="relative z-10 mt-16 md:mt-20 h-screen max-h-[860px] flex items-center overflow-hidden"
        style={{
          backgroundImage: `linear-gradient(rgba(107, 20, 15, 0.65), rgba(107, 20, 15, 0.25)), url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
          backgroundRepeat: "no-repeat",
        }}
      >
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-bold text-5xl md:text-7xl text-white leading-tight">
              Dalal ak jàamm,
            </h1>
            <p className="mt-6 text-2xl md:text-3xl font-light text-white max-w-xl">
              Nassour !
            </p>
          </div>
        </div>

        {/* Bouton Alex superposé au Hero (responsive + safe-area) */}
        <button
          type="button"
          onClick={() => setChatOpen(v => !v)}
          className="
            absolute z-50
            bottom-[max(1rem,env(safe-area-inset-bottom))]
            right-[max(1rem,env(safe-area-inset-right))]
            rounded-full border-2 border-white shadow-xl overflow-hidden cursor-pointer
            focus:outline-none focus:ring-4 focus:ring-white/70
            group
          "
